INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man: The Sequel Wars - Episode Red', 'Mega Man: The Sequel Wars is a fan-made homebrew remake of Mega Man 4, 5 and 6 for the Sega Mega Drive, following in the footsteps of the officially released Mega Man: The Wily Wars. It aims to carefully recreate the NES classics while giving them a fresh 16-bit coat of paint and a rearranged soundtrack. It also aims to improve on the foundation of Wily Wars by enhancing both the presentation and gameplay.' FROM games WHERE igdb_id = 270231 ON CONFLICT (game_id, language_code) DO NOTHING;
