INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Overlord Isn''t Another Isekai Protagonist, Is He?: Chapter 1', 'Have you ever wondered what awaits you after death? At 25, Kay had no plans to die... let alone to wake up in literal HELL one day. Did he deserve such a fate, or is it all just a ridiculous mistake? Kay can’t remember his past, but he firmly believes that he doesn''t belong here.' FROM games WHERE igdb_id = 202528 ON CONFLICT (game_id, language_code) DO NOTHING;
