INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Blade', 'Tiger Blade‘s story casts players in the role of a deadly assassin working for the Horangi chapter of the Tiger Clans. Ordered to steal a mysterious package from a rival chapter, you are shocked to find the object of the heist is a tiger cub. Thought to be extinct for a hundred years, the mythical creature is now desired by every gang in Sewoon and they’ll stop at nothing to take it from you.' FROM games WHERE igdb_id = 266362 ON CONFLICT (game_id, language_code) DO NOTHING;
